17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.rest.controller.AddressResolver;
30	import org.springframework.samples.petclinic.rest.controller.BusinessDayAdjuster;
31	import org.springframework.samples.petclinic.rest.controller.CityCapacityValidator;
32	import org.springframework.samples.petclinic.rest.controller.DailyRegistrationLimitValidator;
33	import org.springframework.samples.petclinic.rest.controller.DisposableEmailDomainValidator;
34	import org.springframework.samples.petclinic.rest.controller.DuplicateIdentityValidator;
35	import org.springframework.samples.petclinic.rest.controller.EmailNormalizer;
36	import org.springframework.samples.petclinic.rest.controller.Households;
37	import org.springframework.samples.petclinic.rest.controller.OwnerAuditLogger;
38	import org.springframework.samples.petclinic.rest.controller.OwnerFieldsValidator;
39	import org.springframework.samples.petclinic.rest.controller.OwnerIdempotencyStore;
40	import org.springframework.samples.petclinic.rest.controller.PossibleDuplicateDetector;
41	import org.springframework.samples.petclinic.rest.controller.PostcodeValidator;
42	import org.springframework.samples.petclinic.rest.controller.RegistrationDateValidator;
43	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
44	import org.springframework.samples.petclinic.model.Owner;
45	import org.springframework.samples.petclinic.model.Pet;
46	import org.springframework.samples.petclinic.model.Visit;
47	import org.springframework.samples.petclinic.rest.api.OwnersApi;
48	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
49	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
50	import org.springframework.samples.petclinic.rest.dto.PetDto;
51	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
52	import org.springframework.samples.petclinic.rest.dto.VisitDto;
53	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
54	import org.springframework.samples.petclinic.service.ClinicService;
55	import org.springframework.security.access.prepost.PreAuthorize;
56	import org.springframework.web.bind.WebDataBinder;
57	import org.springframework.web.bind.annotation.CrossOrigin;
58	import org.springframework.web.bind.annotation.InitBinder;
59	import org.springframework.web.bind.annotation.RequestMapping;
60	import org.springframework.web.bind.annotation.RestController;
61	import org.springframework.web.util.UriComponentsBuilder;
62	
63	import jakarta.transaction.Transactional;
64	
65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    private final OwnerFieldsValidator ownerFieldsValidator;
83	
84	    private final PostcodeValidator postcodeValidator;
85	
86	    private final DisposableEmailDomainValidator disposableEmailDomainValidator;
87	
88	    private final TelephoneNormalizer telephoneNormalizer;
89	
90	    private final EmailNormalizer emailNormalizer;
91	
92	    private final AddressResolver addressResolver;
93	
94	    private final Households households;
95	
96	    private final DuplicateIdentityValidator duplicateIdentityValidator;
97	
98	    private final PossibleDuplicateDetector possibleDuplicateDetector;
99	
100	    private final CityCapacityValidator cityCapacityValidator;
101	
102	    private final DailyRegistrationLimitValidator dailyRegistrationLimitValidator;
103	
104	    private final BusinessDayAdjuster businessDayAdjuster;
105	
106	    private final RegistrationDateValidator registrationDateValidator;
107	
108	    private final OwnerAuditLogger ownerAuditLogger;
109	
110	    private final OwnerIdempotencyStore ownerIdempotencyStore;
111	
112	    public OwnerRestControllerV1(ClinicService clinicService,
113	                                 OwnerMapper ownerMapper,
114	                                 PetMapper petMapper,
115	                                 VisitMapper visitMapper,
116	                                 OwnerFieldsValidator ownerFieldsValidator,
117	                                 PostcodeValidator postcodeValidator,
118	                                 DisposableEmailDomainValidator disposableEmailDomainValidator,
119	                                 TelephoneNormalizer telephoneNormalizer,
120	                                 EmailNormalizer emailNormalizer,
121	                                 AddressResolver addressResolver,
122	                                 Households households,
123	                                 DuplicateIdentityValidator duplicateIdentityValidator,
124	                                 PossibleDuplicateDetector possibleDuplicateDetector,
125	                                 CityCapacityValidator cityCapacityValidator,
126	                                 DailyRegistrationLimitValidator dailyRegistrationLimitValidator,
127	                                 BusinessDayAdjuster businessDayAdjuster,
128	                                 RegistrationDateValidator registrationDateValidator,
129	                                 OwnerAuditLogger ownerAuditLogger,
130	                                 OwnerIdempotencyStore ownerIdempotencyStore) {
131	        this.clinicService = clinicService;
132	        this.ownerMapper = ownerMapper;
133	        this.petMapper = petMapper;
134	        this.visitMapper = visitMapper;
135	        this.ownerFieldsValidator = ownerFieldsValidator;
136	        this.postcodeValidator = postcodeValidator;
137	        this.disposableEmailDomainValidator = disposableEmailDomainValidator;
138	        this.telephoneNormalizer = telephoneNormalizer;
139	        this.emailNormalizer = emailNormalizer;
140	        this.addressResolver = addressResolver;
141	        this.households = households;
142	        this.duplicateIdentityValidator = duplicateIdentityValidator;
143	        this.possibleDuplicateDetector = possibleDuplicateDetector;
144	        this.cityCapacityValidator = cityCapacityValidator;
145	        this.dailyRegistrationLimitValidator = dailyRegistrationLimitValidator;
146	        this.businessDayAdjuster = businessDayAdjuster;
147	        this.registrationDateValidator = registrationDateValidator;
148	        this.ownerAuditLogger = ownerAuditLogger;
149	        this.ownerIdempotencyStore = ownerIdempotencyStore;
150	    }
151	
152	    /**
153	     * Registers the {@link OwnerFieldsValidator} so incoming owner payloads are checked for
154	     * missing or blank mandatory fields as part of the standard {@code @Valid} pass.
155	     */
156	    @InitBinder("ownerFieldsDto")
157	    void initOwnerFieldsBinder(WebDataBinder binder) {
158	        binder.addValidators(ownerFieldsValidator, postcodeValidator, disposableEmailDomainValidator);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
164	        Collection<Owner> owners;
165	        if (lastName != null) {
166	            owners = this.clinicService.findOwnerByLastName(lastName);
167	        } else {
168	            owners = this.clinicService.findAllOwners();
169	        }
170	        if (owners.isEmpty()) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
179	        Owner owner = this.clinicService.findOwnerById(ownerId);
180	        if (owner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
189	        ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
190	        if (replay != null) {
191	            return replay;
192	        }
193	        HttpHeaders headers = new HttpHeaders();
194	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
195	        addressResolver.resolve(owner);
196	        registrationDateValidator.validate(owner.getRegistrationDate());
197	        LocalDate registrationDate = owner.getRegistrationDate() != null
198	            ? owner.getRegistrationDate() : LocalDate.now();
199	        owner.setRegistrationDate(businessDayAdjuster.toBusinessDay(registrationDate));
200	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
201	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
202	        dailyRegistrationLimitValidator.validate(owner.getRegistrationDate());
203	        cityCapacityValidator.validate(owner);
204	        owner.setHouseholdId(households.householdId(owner));
205	        duplicateIdentityValidator.validate(owner);
206	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
207	        if (sharesHousehold) {
208	            // A declared household member is not a suspected duplicate.
209	            owner.setPossibleDuplicate(false);
210	        } else {
211	            possibleDuplicateDetector.detect(owner);
212	        }
213	        this.clinicService.saveOwner(owner);
214	        ownerAuditLogger.logCreated(owner);
215	        ownerIdempotencyStore.record(idempotencyKey, owner.getId());
216	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
217	        headers.setLocation(UriComponentsBuilder.newInstance()
218	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
219	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
220	    }
221	
222	    /**
223	     * If {@code idempotencyKey} has already been used to create an owner that still exists, returns
224	     * that originally created owner with 200 so the repeated create is a no-op; otherwise returns
225	     * {@code null} to let the create proceed normally.
226	     */
227	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
228	        return ownerIdempotencyStore.find(idempotencyKey)
229	            .map(this.clinicService::findOwnerById)
230	            .map(owner -> new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK))
231	            .orElse(null);
232	    }
233	
234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Override
236	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
237	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
238	        if (currentOwner == null) {
239	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	        }
241	        currentOwner.setAddress(ownerFieldsDto.getAddress());
242	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
243	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
244	        addressResolver.resolve(currentOwner);
245	        currentOwner.setCity(ownerFieldsDto.getCity());
246	        currentOwner.setTitle(ownerFieldsDto.getTitle() == null ? null : ownerFieldsDto.getTitle().getValue());
247	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
248	        currentOwner.setLastName(ownerFieldsDto.getLastName());
249	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
250	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
251	        this.clinicService.saveOwner(currentOwner);
252	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
253	    }
254	
255	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
256	    @Transactional
257	    @Override
258	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
259	        Owner owner = this.clinicService.findOwnerById(ownerId);
260	        if (owner == null) {
261	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
262	        }
263	        this.clinicService.deleteOwner(owner);
264	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
265	    }
266	
267	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
268	    @Override
269	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
270	        Owner owner = this.clinicService.findOwnerById(ownerId);
271	        if (owner == null) {
272	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
273	        }
274	        HttpHeaders headers = new HttpHeaders();
275	        Pet pet = petMapper.toPet(petFieldsDto);
276	        owner.setId(ownerId);
277	        pet.setOwner(owner);
278	        pet.getType().setName(null);
279	        this.clinicService.savePet(pet);
280	        PetDto petDto = petMapper.toPetDto(pet);
281	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
282	            .buildAndExpand(pet.getId()).toUri());
283	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
284	    }
285	
286	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
287	    @Override
288	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
289	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
290	        if (currentOwner != null) {
291	            Pet currentPet = this.clinicService.findPetById(petId);
292	            if (currentPet != null) {
293	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
294	                currentPet.setName(petFieldsDto.getName());
295	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
296	                this.clinicService.savePet(currentPet);
297	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
298	            }
299	        }
300	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
301	    }
302	
303	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
304	    @Override
305	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
306	        HttpHeaders headers = new HttpHeaders();
307	        Visit visit = visitMapper.toVisit(visitFieldsDto);
308	        Pet pet = new Pet();
309	        pet.setId(petId);
310	        visit.setPet(pet);
311	        this.clinicService.saveVisit(visit);
312	        VisitDto visitDto = visitMapper.toVisitDto(visit);
313	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
314	            .buildAndExpand(visit.getId()).toUri());
315	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
316	    }
317	
318	
319	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
320	    @Override
321	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
322	        Owner owner = this.clinicService.findOwnerById(ownerId);
323	        if (owner != null) {
324	            Pet pet = owner.getPet(petId);
325	            if (pet != null) {
326	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
327	            }
328	        }
329	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
330	    }
331	}
